import{bV as e,aL as r,u as l,G as t}from"./chunks/framework.DxlKcdLe.js";const f=JSON.parse('{"title":"Cloudflare免费节点搭建详细教程","description":"","frontmatter":{"title":"Cloudflare免费节点搭建详细教程","date":"2026-04-12T22:52:54.000Z","permalink":"/pages/c98fb2/","categories":["更多","服务器实例"],"tags":["Cloudflare","Workers","代理"]},"headers":[],"relativePath":"pages/c98fb2.md","filePath":"更多/服务器实例/03.Cloudflare免费节点搭建详细教程.md","lastUpdated":1785138377000}'),i={name:"pages/c98fb2.md"};function o(n,a,h,s,c,d){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="cloudflare-免费节点搭建详细教程-已绑定域名版" tabindex="-1">Cloudflare 免费节点搭建详细教程（已绑定域名版） <a class="header-anchor" href="#cloudflare-免费节点搭建详细教程-已绑定域名版" aria-label="Permalink to &quot;Cloudflare 免费节点搭建详细教程（已绑定域名版）&quot;">​</a></h1><p>你的域名后台地址：<a href="https://cfkv.kcshen.cn/admin" target="_blank" rel="noreferrer">https://cfkv.kcshen.cn/admin</a></p><hr><h2 id="🧱-一、准备工作" tabindex="-1">🧱 一、准备工作 <a class="header-anchor" href="#🧱-一、准备工作" aria-label="Permalink to &quot;🧱 一、准备工作&quot;">​</a></h2><p>你已经完成：</p><ul><li>✅ 拥有域名 <a href="https://cfkv.kcshen.cn" target="_blank" rel="noreferrer">cfkv.kcshen.cn</a>（尚无域名可到 <a href="https://www.dnshe.com/" target="_blank" rel="noreferrer">DNSHE</a> 免费注册）</li><li>✅ 域名已接入 Cloudflare</li></ul><p>接下来只需要完成 KV + Pages + 绑定 + 配置</p><hr><h2 id="🗄️-二、创建-kv-存储-必须" tabindex="-1">🗄️ 二、创建 KV 存储（必须） <a class="header-anchor" href="#🗄️-二、创建-kv-存储-必须" aria-label="Permalink to &quot;🗄️ 二、创建 KV 存储（必须）&quot;">​</a></h2><h3 id="步骤" tabindex="-1">步骤： <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤：&quot;">​</a></h3><ol><li>登录 <a href="https://dash.cloudflare.com/" target="_blank" rel="noreferrer">Cloudflare 控制台</a></li><li>进入：Storage &amp; Databases → KV</li><li>点击 Create Namespace</li><li>命名（例如）：cfkv</li></ol><hr><h2 id="📦-三、创建-pages-项目" tabindex="-1">📦 三、创建 Pages 项目 <a class="header-anchor" href="#📦-三、创建-pages-项目" aria-label="Permalink to &quot;📦 三、创建 Pages 项目&quot;">​</a></h2><h3 id="上传-zip" tabindex="-1">上传 ZIP <a class="header-anchor" href="#上传-zip" aria-label="Permalink to &quot;上传 ZIP&quot;">​</a></h3><ol><li>Workers &amp; Pages → Create → Pages</li><li>选择 Upload assets</li><li>上传项目源码（main.zip）</li></ol><h3 id="构建设置" tabindex="-1">构建设置 <a class="header-anchor" href="#构建设置" aria-label="Permalink to &quot;构建设置&quot;">​</a></h3><ul><li>Build command: 留空</li><li>Output directory: /</li></ul><hr><h2 id="🔐-四、配置环境变量-非常关键" tabindex="-1">🔐 四、配置环境变量（非常关键） <a class="header-anchor" href="#🔐-四、配置环境变量-非常关键" aria-label="Permalink to &quot;🔐 四、配置环境变量（非常关键）&quot;">​</a></h2><p>路径：Settings → Environment Variables</p><p>添加：</p><p>ADMIN = 你的后台密码</p><hr><h2 id="🔁-五、重新部署" tabindex="-1">🔁 五、重新部署 <a class="header-anchor" href="#🔁-五、重新部署" aria-label="Permalink to &quot;🔁 五、重新部署&quot;">​</a></h2><p>路径：Deployments → Retry deployment</p><hr><h2 id="🔗-六、绑定-kv-命名空间" tabindex="-1">🔗 六、绑定 KV 命名空间 <a class="header-anchor" href="#🔗-六、绑定-kv-命名空间" aria-label="Permalink to &quot;🔗 六、绑定 KV 命名空间&quot;">​</a></h2><p>路径：Settings → Functions → KV Namespace Bindings</p><ul><li>Variable name: KV</li><li>KV namespace: cfkv</li></ul><hr><h2 id="🌐-七、绑定域名" tabindex="-1">🌐 七、绑定域名 <a class="header-anchor" href="#🌐-七、绑定域名" aria-label="Permalink to &quot;🌐 七、绑定域名&quot;">​</a></h2><p><a href="https://cfkv.kcshen.cn" target="_blank" rel="noreferrer">cfkv.kcshen.cn</a> → CNAME → <code>xxx.pages.dev</code>（Pages 项目分配的子域）<br> 开启 Cloudflare 代理（橙色云）</p><hr><h2 id="🔑-八、访问后台" tabindex="-1">🔑 八、访问后台 <a class="header-anchor" href="#🔑-八、访问后台" aria-label="Permalink to &quot;🔑 八、访问后台&quot;">​</a></h2><p>浏览器打开：<a href="https://cfkv.kcshen.cn/admin" target="_blank" rel="noreferrer">https://cfkv.kcshen.cn/admin</a></p>',35)])])}const u=e(i,[["render",o]]);export{f as __pageData,u as default};
